import 'package:dio/dio.dart';abstract class Failure {  final String errMessage;  const Failure(this.errMessage);}class ServerFailure extends Failure {  const ServerFailure(super.errMessage);  static Failure fromDioError(DioException error) {    if (error.response?.statusCode == 401) {      return const UnauthenticatedFailure();    }    if (error.response != null) {      final serverMessage = _extractServerMessage(error.response?.data);      if (serverMessage.isNotEmpty) {        return ServerFailure(serverMessage);      }      if (error.response?.statusCode != null) {        return ServerFailure(_handleStatusCode(error.response!.statusCode!));      }    }    return ServerFailure(_handleDioError(error));  }  static String _handleStatusCode(int statusCode) {    switch (statusCode) {      case 400:        return "🔴 Bad request. Please check your input.";      case 402:        return "💰 Payment required. Please check your payment details.";      case 403:        return "🚫 Forbidden access.";      case 404:        return "🔍 Resource not found.";      case 405:        return "❌ Method not allowed.";      case 408:        return "⏳ Request timeout. Please try again later.";      case 429:        return "⚠️ Too many requests. Please slow down.";      case 500:        return "🔥 Internal server error.";      case 502:        return "🌐 Bad gateway.";      case 503:        return "🚧 Service unavailable.";      case 504:        return "⏱ Gateway timeout.";      default:        return "❓ Unexpected error occurred. Status code: $statusCode";    }  }  static String _handleDioError(DioException error) {    switch (error.type) {      case DioExceptionType.connectionTimeout:        return "⏳ Connection timeout. Please check your internet connection.";      case DioExceptionType.sendTimeout:        return "📤 Send timeout. The request took too long to send.";      case DioExceptionType.receiveTimeout:        return "📥 Receive timeout. Server response took too long.";      case DioExceptionType.badCertificate:        return "🔐 Invalid SSL Certificate.";      case DioExceptionType.badResponse:        return "⚠️ Invalid response from the server.";      case DioExceptionType.cancel:        return "❌ Request was cancelled.";      case DioExceptionType.connectionError:        return "📶 No internet connection.";      default:        return "❓ An unknown error occurred. Please try again.";    }  }  static String _extractServerMessage(dynamic data) {    if (data is Map<String, dynamic>) {      return data['message']?.toString() ?? data['error']?.toString() ?? '';    }    return data?.toString() ?? '';  }}class UnauthenticatedFailure extends Failure {  const UnauthenticatedFailure()      : super("🔑 Unauthorized access. Please log in again.");}